+export const getRelatedBooks = async (req, res) => {
+   
+  try {
+      const books = await Book.find().sort({ createdAt: -1 });
+    
+     return  res.status(200).json({ books }); 
+  } catch (error) {
+    res.status(400).json({message:'Unable to fetch books', error})  
+  }
+}
